pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 1 wei);
        vm.prank(alice);
        c.deposit{value: 1 wei}();
        uint256 aliceBalanceBeforeRefund = alice.balance;
        vm.prank(alice);
        c.refund();
        uint256 aliceBalanceAfterRefund = alice.balance;
        // In reference: deposit added 1 wei to balance, refund sends 1 wei back, so alice gets 1 wei more.
        // In buggy: deposit does nothing, refund sends 0 wei, alice balance unchanged.
        assertTrue(aliceBalanceAfterRefund == aliceBalanceBeforeRefund + 1 wei);
    }
}

