pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use a non-creator user for the later deposit attempt
        address user = address(0x1234);
        vm.deal(address(this), 10 wei);
        // Creator (this contract in setUp) deposits 1 wei
        vm.deal(address(this), 1 wei);
        c.deposit{value: 1 wei}();
        // Creator calls migrateTo to itself
        c.migrateTo(address(this));
        // Now try to deposit again by another user
        vm.deal(user, 1 wei);
        vm.prank(user);
        bool ok;
        try c.deposit{value: 1 wei}() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: deposit succeeds (contract alive), bug: deposit reverts (contract destroyed)
        assertTrue(ok == true);
    }
}

