pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 10 wei via deposit from someone
        address user = address(0x1);
        vm.deal(user, 10 wei);
        vm.prank(user);
        c.deposit{value: 10 wei}();

        // Creator migrates to a recipient
        address recipient = address(0x2);
        c.migrateTo(recipient);

        // After migration, the correct contract sends all balance (10 wei), so contract balance = 0
        // The buggy contract sends only 1 wei, so contract balance = 9 wei
        assertTrue(address(c).balance == 0, "contract balance should be 0 after correct migration");
    }
}

