import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address user = address(0x1234);
        address target = address(0x5678);
        // Give user some ether to deposit
        vm.deal(user, 1 wei);
        vm.prank(user);
        c.deposit{value: 1 wei}();
        // Get the contract's balance before migration
        uint256 balanceBefore = address(c).balance;
        // Call migrateTo as the creator
        vm.prank(address(this)); // creator is the deployer (this contract)
        c.migrateTo(target);
        uint256 balanceAfter = address(c).balance;
        // The reference contract should transfer the balance, so balanceAfter should be 0
        // The buggy contract does not transfer, so balanceAfter equals balanceBefore (1 wei)
        assertTrue(balanceAfter == 0 ether);
    }
}

